 async function sourcePixel(progress=0,u=.5,v=.5){return page.$eval('.nw-motion-dialog iframe',async(f,{progress,u,v})=>{const d=f.contentDocument,imgs=Array.from(d.querySelectorAll('[data-nw-stream-slot] img'));await Promise.all(imgs.slice(1).map(async img=>{img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="320" height="320"/>');await img.decode();}));f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const node=d.querySelector('[data-nw-stream-slot]'),r=node.__nwMotionInstances[0].homography,p=NAGWEB_STREAM_MODEL.projectPlane(r.matrix,u*r.width,v*r.height),c=d.querySelector('.nw-ring-surface'),host=node.offsetParent,scale=c.width/host.clientWidth;return{pixel:Array.from(c.getContext('2d').getImageData(Math.floor(p.x*scale),Math.floor(p.y*scale),1,1).data),x:p.x,y:p.y};},{progress,u,v});}
