  await page.$eval('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]',input=>{const svg='<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300"><rect width="100" height="300" fill="red"/><rect x="100" width="100" height="300" fill="lime"/><rect x="200" width="100" height="300" fill="blue"/></svg>',transfer=new DataTransfer();transfer.items.add(new File([svg],'Rear.svg',{type:'image/svg+xml'}));input.files=transfer.files;input.dispatchEvent(new Event('change',{bubbles:true}));});await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe').contentDocument.querySelector('[data-id="'+id+'"] img')?.naturalWidth===300,{},start[0].id);await ready();const rearRed=await sourcePixel(.5,.17),rearBlue=await sourcePixel(.5,.83);assert.ok(rearRed.x>rearBlue.x);assert.ok(rearRed.pixel[0]>250&&rearRed.pixel[2]<5&&rearBlue.pixel[2]>250&&rearBlue.pixel[0]<5);assert.ok(Math.abs(rearRed.pixel[3]-.45*255)<5);console.log('Cover Ring pixels: rounded depth picking, single plane fade/composite, both texture axes, foreground/rear crop, mirrored rear faces and bounded tiles OK');
